        int i = 2;
        while (i <= Math.sqrt(n)) {
            if (n % i == 0) {
                fact.add(i);
                n /= i;
            } else {
                i += 1;
            }
        }
        if (n > 1) {
            fact.add(n);
        }
        return fact;
    }
}
